import { readFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { pathToFileURL } from 'node:url';

const compareIds = (a, b) => a < b ? -1 : a > b ? 1 : 0;
const validId = id => typeof id === 'string' && id.length > 0;

export function planJobs(spec) {
  if (!Array.isArray(spec)) throw new Error('Expected an array of jobs');
  const jobs = new Map();
  for (const job of spec) {
    if (job === null || typeof job !== 'object' || Array.isArray(job) ||
        !validId(job.id) || !Array.isArray(job.deps) ||
        !['pending', 'succeeded', 'failed'].includes(job.state)) {
      throw new Error('Invalid job fields');
    }
    if (jobs.has(job.id)) throw new Error('Duplicate job ID');
    const deps = new Set();
    for (const dep of job.deps) {
      if (!validId(dep) || deps.has(dep)) throw new Error('Invalid or duplicate dependency');
      deps.add(dep);
    }
    jobs.set(job.id, { id: job.id, deps, state: job.state, children: [],
      remaining: deps.size, causes: new Set() });
  }
  for (const job of jobs.values()) {
    for (const dep of job.deps) {
      if (!jobs.has(dep)) throw new Error('Unknown dependency');
      jobs.get(dep).children.push(job.id);
    }
  }

  // Keep the frontier sorted after each insertion, not just between waves.
  const frontier = [];
  function enqueue(id) {
    let low = 0, high = frontier.length;
    while (low < high) {
      const mid = Math.floor((low + high) / 2);
      if (compareIds(frontier[mid], id) < 0) low = mid + 1;
      else high = mid;
    }
    frontier.splice(low, 0, id);
  }
  for (const job of jobs.values()) {
    if (job.remaining === 0) enqueue(job.id);
  }
  const order = [], ready = [], blocked = [];
  let visited = 0;
  while (frontier.length) {
    const id = frontier.shift();
    const job = jobs.get(id);
    visited++;
    if (job.state === 'pending') {
      if (job.causes.size) {
        blocked.push({ id, causes: [...job.causes].sort(compareIds) });
      } else {
        order.push(id);
        if ([...job.deps].every(dep => jobs.get(dep).state === 'succeeded')) ready.push(id);
      }
    }
    // Propagate ancestry regardless of the intermediate job's state.
    for (const childId of job.children) {
      const child = jobs.get(childId);
      for (const cause of job.causes) child.causes.add(cause);
      if (job.state === 'failed') child.causes.add(id);
      if (--child.remaining === 0) enqueue(childId);
    }
  }
  if (visited !== jobs.size) throw new Error('Dependency cycle');
  ready.sort(compareIds);
  blocked.sort((a, b) => compareIds(a.id, b.id));
  return { order, ready, blocked };
}

if (process.argv[1] && pathToFileURL(resolve(process.argv[1])).href === import.meta.url) {
  try {
    if (process.argv.length !== 3) throw new Error('Usage: node job-plan.js SPECFILE');
    const spec = JSON.parse(readFileSync(process.argv[2], 'utf8'));
    process.stdout.write(JSON.stringify(planJobs(spec)) + '\n');
  } catch (error) {
    process.stderr.write(`job-plan: ${error.message}\n`);
    process.exitCode = 2;
  }
}

import test from 'node:test';
import assert from 'node:assert/strict';
import { mkdtempSync, writeFileSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { spawnSync } from 'node:child_process';
import { planJobs } from '../job-plan.js';

const job = (id, deps = [], state = 'pending') => ({ id, deps, state });

test('full-graph ordering is filtered only after Kahn selection', () => {
  assert.deepEqual(planJobs([job('a', ['z']), job('b'), job('z', [], 'succeeded')]), {
    order: ['b', 'a'], ready: ['a', 'b'], blocked: [],
  });
  assert.deepEqual(planJobs([job('z'), job('b'), job('a', ['b'])]), {
    order: ['b', 'a', 'z'], ready: ['b', 'z'], blocked: [],
  });
});

test('all failed ancestry survives failed and succeeded intermediates', () => {
  const spec = [job('f2', ['f1'], 'failed'), job('f1', [], 'failed'),
    job('success', ['f2'], 'succeeded'), job('end', ['success', 'f1']),
    job('middle', ['f2']), job('good', [], 'succeeded'), job('next', ['good'])];
  assert.deepEqual(planJobs(spec), {
    order: ['next'], ready: ['next'], blocked: [
      { id: 'end', causes: ['f1', 'f2'] }, { id: 'middle', causes: ['f1', 'f2'] },
    ],
  });
  assert.deepEqual(planJobs([...spec].reverse()), planJobs(spec));
});

test('IDs retain whitespace, Unicode, and prototype-like names without mutation', () => {
  const ids = ['\ue000', '😀', 'é', 'a', 'Z', '__proto__', 'constructor', ' '];
  const sorted = [' ', 'Z', '__proto__', 'a', 'constructor', 'é', '😀', '\ue000'];
  const spec = Object.freeze(ids.map(id => Object.freeze({
    id, deps: Object.freeze([]), state: 'pending', ignored: true,
  })));
  assert.deepEqual(planJobs(spec), { order: sorted, ready: sorted, blocked: [] });
  assert.deepEqual(planJobs([job('__proto__', [], 'failed'), job('constructor', ['__proto__'])]), {
    order: [], ready: [], blocked: [{ id: 'constructor', causes: ['__proto__'] }],
  });
});

test('reject malformed fields, duplicate IDs/dependencies and missing references synchronously', () => {
  const invalid = [null, {}, 'jobs', [null], [[]], [{}],
    [{ id: '', deps: [], state: 'pending' }],
    [{ id: 1, deps: [], state: 'pending' }],
    [{ id: 'a', state: 'pending' }],
    [{ id: 'a', deps: null, state: 'pending' }],
    [{ id: 'a', deps: [], state: undefined }],
    [{ id: 'a', deps: [] }],
    [{ id: 'a', deps: [], state: 'Pending' }],
    [job('a', [''])], [job('a', [1])], [job('a', [null])],
    [job('a', ['missing'])], [job('a'), job('a')],
    [job('a'), job('b', ['a', 'a'])], new Array(1),
    [{ id: 'a', deps: new Array(1), state: 'pending' }]];
  for (const spec of invalid) assert.throws(() => planJobs(spec), Error);
});

test('reject cycles even when no pending job is involved', () => {
  for (const state of ['pending', 'succeeded', 'failed']) {
    assert.throws(() => planJobs([job('self', ['self'], state)]), Error);
    assert.throws(() => planJobs([
      job('ok'), job('a', ['b'], state), job('b', ['a'], state),
    ]), Error);
  }
});

test('CLI success, argument errors, file errors, parse errors and graph errors', () => {
  const dir = mkdtempSync(join(tmpdir(), 'job-plan-test-'));
  const cli = fileURLToPath(new URL('../job-plan.js', import.meta.url));
  const run = args => spawnSync(process.execPath, [cli, ...args], { encoding: 'utf8' });
  function failure(args) {
    const result = run(args);
    assert.equal(result.error, undefined);
    assert.equal(result.status, 2);
    assert.equal(result.stdout, '');
    assert.ok(result.stderr.length > 0);
  }
  try {
    const valid = join(dir, 'valid.json');
    writeFileSync(valid, JSON.stringify([job('é')]));
    const result = run([valid]);
    assert.equal(result.error, undefined);
    assert.equal(result.status, 0);
    assert.equal(result.stderr, '');
    assert.equal(result.stdout, '{"order":["é"],"ready":["é"],"blocked":[]}\n');
    failure([]);
    failure([valid, valid]);
    failure([join(dir, 'absent.json')]);
    failure([dir]);
    for (const [name, content] of [['parse.json', '{'], ['graph.json', JSON.stringify([job('x', ['x'])])], ['fields.json', '{}']]) {
      const path = join(dir, name);
      writeFileSync(path, content);
      failure([path]);
    }
    const imported = spawnSync(process.execPath, ['--input-type=module', '-e',
      `await import(${JSON.stringify(new URL('../job-plan.js', import.meta.url).href)})`], { encoding: 'utf8' });
    assert.equal(imported.status, 0);
    assert.equal(imported.stdout, '');
    assert.equal(imported.stderr, '');
  } finally {
    rmSync(dir, { recursive: true, force: true });
  }
});

